import { beforeAll, describe, expect, it } from 'vitest';
import { makeJpeg, makePng, makeWebp } from './fixtures.js';
import { detectType, looksLikeMarkup, looksLikeText, safeFilename } from './type-check.js';

/* Real files, generated by a real encoder — see fixtures.ts on why a
   hand-written signature is the wrong fixture for a signature check. */
let PNG: Buffer;
let JPEG: Buffer;
let WEBP: Buffer;

beforeAll(async () => {
  [PNG, JPEG, WEBP] = await Promise.all([makePng(), makeJpeg(), makeWebp()]);
});

const GIF = Buffer.concat([Buffer.from('GIF89a', 'latin1'), Buffer.alloc(64)]);
const PDF = Buffer.concat([Buffer.from('%PDF-1.7\n', 'latin1'), Buffer.alloc(64)]);
const ZIP = Buffer.concat([Buffer.from([0x50, 0x4b, 0x03, 0x04]), Buffer.alloc(64)]);
const ELF = Buffer.concat([Buffer.from([0x7f, 0x45, 0x4c, 0x46]), Buffer.alloc(64)]);

describe('the type is decided by the bytes', () => {
  it('accepts the formats a support conversation needs', async () => {
    expect(await detectType(PNG)).toMatchObject({ ok: true, mimeType: 'image/png', image: true });
    expect(await detectType(JPEG)).toMatchObject({ ok: true, mimeType: 'image/jpeg', image: true });
    expect(await detectType(WEBP)).toMatchObject({ ok: true, mimeType: 'image/webp', image: true });
    expect(await detectType(PDF)).toMatchObject({ ok: true, mimeType: 'application/pdf' });
    expect(await detectType(Buffer.from('error log line 1\n'))).toMatchObject({
      ok: true,
      mimeType: 'text/plain',
    });
  });

  /* The attack this closes: `shell.php` renamed to `holiday.jpg` arrives with
     a .jpg extension and Content-Type: image/jpeg, and every check that reads
     those two fields passes it. Neither is consulted here. */
  it('is not fooled by a renamed executable', async () => {
    expect(await detectType(ELF)).toMatchObject({ ok: false, reason: 'not_allowed' });
  });

  it('refuses archives, which hide their contents from every check here', async () => {
    expect(await detectType(ZIP)).toMatchObject({ ok: false, reason: 'not_allowed' });
  });

  /* GIF is a real image format and still refused: the allowlist is the list
     of formats whose risk is understood, not the list of things that decode. */
  it('refuses a format simply because it is not on the list', async () => {
    expect(await detectType(GIF)).toMatchObject({ ok: false, detected: 'image/gif' });
  });

  /* SVG is a document with a script element, not an image. Rendering one in
     our origin is stored XSS, and sanitising SVG is a losing arms race. */
  it('refuses SVG', async () => {
    const svg = Buffer.from(
      '<svg xmlns="http://www.w3.org/2000/svg"><script>alert(1)</script></svg>',
    );
    expect(await detectType(svg)).toMatchObject({ ok: false });
  });

  it('refuses an empty file', async () => {
    expect(await detectType(Buffer.alloc(0))).toMatchObject({ ok: false, reason: 'empty' });
  });

  /* `file-type` finds the PDF signature wherever it appears. Requiring it at
     offset 0 refuses a polyglot whose first bytes are something else. */
  it('refuses a PDF signature that is not at the start', async () => {
    const polyglot = Buffer.concat([
      Buffer.from('GIF89a'),
      Buffer.from('%PDF-1.7\n'),
      Buffer.alloc(64),
    ]);
    expect(await detectType(polyglot)).toMatchObject({ ok: false });
  });

  /* Text has no signature, so it is the one type decided by exclusion — and
     the exclusion has to be strict, or "unknown binary" becomes "text". */
  it('does not call arbitrary binary data text', async () => {
    const random = Buffer.from([0x01, 0x02, 0x00, 0xff, 0xfe, 0x7f]);
    expect(await detectType(random)).toMatchObject({ ok: false, reason: 'unknown' });
  });

  it('refuses a .txt that is really markup', async () => {
    expect(await detectType(Buffer.from('<script>alert(1)</script>'))).toMatchObject({
      ok: false,
    });
    expect(await detectType(Buffer.from('<?php system($_GET[0]); ?>'))).toMatchObject({
      ok: false,
    });
  });
});

describe('looksLikeText', () => {
  it('accepts a log file, including Arabic', () => {
    expect(looksLikeText(Buffer.from('2026-10-25 ERROR spooler\tstopped\r\n'))).toBe(true);
    expect(looksLikeText(Buffer.from('الطابعة توقفت بعد التحديث'))).toBe(true);
  });

  it('rejects anything with a NUL byte', () => {
    expect(looksLikeText(Buffer.from([0x68, 0x00, 0x69]))).toBe(false);
  });

  it('rejects invalid UTF-8 and control characters', () => {
    expect(looksLikeText(Buffer.from([0xc3, 0x28]))).toBe(false);
    expect(looksLikeText(Buffer.from([0x68, 0x07, 0x69]))).toBe(false);
  });
});

describe('looksLikeMarkup', () => {
  it('finds markup regardless of spacing or case', () => {
    expect(looksLikeMarkup(Buffer.from('< SCRIPT >'))).toBe(true);
    expect(looksLikeMarkup(Buffer.from('<IFRAME src=x>'))).toBe(true);
  });

  it('leaves ordinary prose alone', () => {
    expect(looksLikeMarkup(Buffer.from('the value was < 5 and > 2'))).toBe(false);
  });
});

describe('safeFilename', () => {
  /* The stored name is shown in the interface and ends up in a
     Content-Disposition header. A newline splits the response; a quote breaks
     out of the parameter; a separator makes it a path. */
  it('keeps only a basename', () => {
    expect(safeFilename('../../etc/passwd', 'txt')).toBe('passwd.txt');
    expect(safeFilename('C:\\Windows\\system32\\cmd.exe', 'txt')).toBe('cmd.exe.txt');
  });

  it('strips quotes and control characters', () => {
    expect(safeFilename('in"voice\r\nSet-Cookie: x=1', 'pdf')).toBe('invoiceSet-Cookie: x=1.pdf');
    expect(safeFilename("it's.png", 'png')).toBe('its.png');
  });

  it('forces the extension to match what the bytes actually are', () => {
    expect(safeFilename('photo.jpg', 'png')).toBe('photo.jpg.png');
    expect(safeFilename('report.pdf', 'pdf')).toBe('report.pdf');
  });

  it('copes with no filename at all', () => {
    expect(safeFilename(undefined, 'png')).toBe('attachment.png');
    expect(safeFilename('', 'png')).toBe('attachment.png');
  });

  it('keeps a non-Latin name readable', () => {
    expect(safeFilename('فاتورة.pdf', 'pdf')).toBe('فاتورة.pdf');
  });
});
